"use client";

import React, { useState } from "react";
import { api } from "@/lib/api";
import { getPlans } from "@/lib/pricing";

export default function PricingPage() {
  const plans = getPlans();
  const [loadingId, setLoadingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function handleSelect(planId: string) {
    try {
      setError(null);
      setLoadingId(planId);
      const { redirectUrl } = await api.createStripeCheckoutSession(
        planId as any
      );
      window.location.href = redirectUrl;
    } catch (err: any) {
      console.error(err);
      setError(err?.message ?? "Could not start checkout.");
      setLoadingId(null);
    }
  }

  return (
    <div className="min-h-screen bg-dark-bg flex flex-col items-center justify-center p-6">
      <div className="text-center mb-10">
        <h1 className="text-4xl font-bold">Choose your plan</h1>
        <p className="text-dark-text-secondary mt-2 max-w-2xl">
          Sylor.ai automates lead followup, SMS and booking. Pick the plan that fits your crew.
        </p>
        {error ? (
          <p className="text-red-400 mt-3 text-sm">{error}</p>
        ) : null}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-4xl w-full">
        {plans.map((plan, idx) => (
          <div
            key={plan.id}
            className={`bg-dark-card border border-glass-border rounded-xl p-8 flex flex-col ${
              idx === 1 ? "border-brand-primary" : ""
            }`}
          >
            {idx === 1 && (
              <span className="bg-brand-primary px-3 py-1 rounded-full text-xs font-semibold self-center -mt-12 mb-8">
                MOST POPULAR
              </span>
            )}
            <h3 className="text-2xl font-semibold">{plan.name}</h3>
            <p className="text-dark-text-secondary mt-3">
              Best for small teams.
            </p>
            <div className="mt-6 flex items-end gap-2">
              <span className="text-5xl font-bold">${plan.price}</span>
              <span className="text-dark-text-secondary mb-2">/mo</span>
            </div>
            <ul className="mt-6 space-y-2 text-dark-text-secondary">
              {plan.features.map((f) => (
                <li key={f}>• {f}</li>
              ))}
            </ul>
            <button
              onClick={() => handleSelect(plan.id)}
              disabled={loadingId === plan.id}
              className={`mt-8 w-full py-3 rounded-lg font-semibold ${
                idx === 1
                  ? "bg-brand-primary"
                  : "bg-slate-700 hover:bg-slate-600"
              }`}
            >
              {loadingId === plan.id ? "Redirecting..." : "Get started"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
